-- Yearly electricity generation, capacity, emissions, and demand for 200+ countries.
-- Auto-generated by scripts/gen_evidence_pages.py: 118,463 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("DATE") as year, count(*) as records
from THE_LIBRARY.ENERGY_ENVIRONMENT.ELECTRICITY_BY_COUNTRY
where "DATE" is not null
group by 1
order by 1
